function r=input_record(p,expected),assert(isfile(p)&&strcmpi(sha256_file(p),expected),'SCREEN12:InputSHA','Input SHA mismatch: %s',p);r=struct('path',p,'sha256',lower(expected));end
function h=json_sha256(x),b=unicode2native(jsonencode(x),'UTF-8');md=java.security.MessageDigest.getInstance('SHA-256');md.update(uint8(b(:)));h=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));end
function h=normalizer_sha(m),md=java.security.MessageDigest.getInstance('SHA-256');for n={'input_mu','input_sigma'},f=n{1};a=reshape(double(m.(f)),1,[]);hdr=[f char(0) '((1, 14), ''float64'')' char(0)];md.update(typecast(uint8(unicode2native(hdr,'UTF-8')),'int8'));md.update(typecast(a(:),'int8'));end;h=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));end
function h=sha256_file(p),fid=fopen(p,'r');assert(fid>=0,'SCREEN12:Read','Cannot read %s',p);cl=onCleanup(@()fclose(fid));md=java.security.MessageDigest.getInstance('SHA-256');while true,b=fread(fid,8*1024*1024,'*uint8');if isempty(b),break;end;md.update(b);end;h=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));clear cl;end
function mkdir_if_missing(p),if ~isfolder(p),mkdir(p);end;end
function write_json(p,x),fid=fopen(p,'w');assert(fid>=0,'SCREEN12:Write','Cannot write manifest.');cl=onCleanup(@()fclose(fid));fwrite(fid,[jsonencode(x,'PrettyPrint',true) newline],'char');clear cl;end
